  currentness: LocalBlobUrlCurrentnessFacts,
  geometry: ImageLocalDisplayGeometryObservation | null,
  selection: ImageLocalDisplayCropSelection,
  rotationIndex: number,
  mirroredHorizontally = false,
  mirroredVertically = false,
): ImageLocalDisplayViewCropPngExportPlan | null {
  const crop = planImageLocalDisplayCropPngExport(currentness, geometry, selection);
  if (crop === null) return null;
  if (typeof mirroredHorizontally !== 'boolean'
    || typeof mirroredVertically !== 'boolean') {
    throw new Error('runtime-media-image-local-display-view-crop-export-mirror-mismatch');
  }
  const rotationDegrees = IMAGE_LOCAL_DISPLAY_ROTATION_DEGREES[rotationIndex];
  if (rotationDegrees === undefined) {
    throw new Error('runtime-media-image-local-display-view-crop-export-angle-mismatch');
  }
  const swapsAxes = rotationIndex % 2 === 1;
  const outputWidth = swapsAxes ? crop.cropHeight : crop.cropWidth;
  const outputHeight = swapsAxes ? crop.cropWidth : crop.cropHeight;
  const mirrorLabel = `${mirroredHorizontally ? '-mirror-horizontal' : ''}${
    mirroredVertically ? '-mirror-vertical' : ''}`;
  return {
    rotationIndex,
    rotationDegrees,
    mirroredHorizontally,
    mirroredVertically,
    sourceWidth: crop.sourceWidth,
    sourceHeight: crop.sourceHeight,
    cropX: crop.cropX,
    cropY: crop.cropY,
    cropWidth: crop.cropWidth,
    cropHeight: crop.cropHeight,
    outputWidth,
    outputHeight,
    canvasTransform: imageLocalDisplayCanvasTransform(
      crop.cropWidth,
      crop.cropHeight,
      rotationDegrees,
      mirroredHorizontally,
      mirroredVertically,
