function imageLocalDisplayCanvasTransform(
  sourceWidth: number,
  sourceHeight: number,
  rotationDegrees: 0 | 90 | 180 | 270,
  mirroredHorizontally: boolean,
  mirroredVertically: boolean,
): [number, number, number, number, number, number] {
  let [a, b, c, d, e, f] = rotationDegrees === 0
    ? [1, 0, 0, 1, 0, 0]
    : rotationDegrees === 90
      ? [0, 1, -1, 0, sourceHeight, 0]
      : rotationDegrees === 180
        ? [-1, 0, 0, -1, sourceWidth, sourceHeight]
        : [0, -1, 1, 0, 0, sourceWidth];
  if (mirroredHorizontally) {
    e += a * sourceWidth;
    f += b * sourceWidth;
    a = -a;
    b = -b;
  }
  if (mirroredVertically) {
    e += c * sourceHeight;
    f += d * sourceHeight;
    c = -c;
    d = -d;
  }
